style.css:
@-moz-document domain("chat.openai.com") {
h1 span {
        visibility: hidden;
        position: relative;
    }
    h1 span::after {
        content: "Cần giúp gì nè?"; 
        visibility: visible;
        position: absolute;
        top: 0;
        left: 0;
        font-size: 24px;
        font-weight: bold;
        color: #ff66b2;
    }
}
